GT2 = r'''# ---- 0.3.54 GearTheme (2/2): the worn ACTIVE theme pieces per set (one armor slot each), the bonuses of the reached tiers (totals + hp)
M(gthm, r"""
public static int[] counts(java.util.UUID u, @IC@ armor) {
  int[] c = new int[SKEY.length];
  if (armor == null) return c;
  for (int k = 0; k < armor.getCapacity(); k++) {
    @IS@ s = armor.getItemStack((short) k);
    if (s == null || s.isEmpty()) continue;
    String id = s.getItemId();
    int i = piece(id);
    if (i < 0 || @PKG@.GearData.slotOf(id) != 2) continue;
    @BD@ d = @PKG@.GearData.effective(id, s.getMetadata());
    if (!@PKG@.GearStats.active(u, id, d)) continue;
    c[ASET[i]] = c[ASET[i]] + 1;
  }
  return c;
}""")
M(gthm, r"""
public static int[] note(java.util.UUID u, @IC@ armor) {
  int[] c = counts(u, armor);
  if (u != null) WORN.put(@PKG@.Gear.pkey(u), c);
  return c;
}""")
M(gthm, r"""
public static int addTo(int[] tot, java.util.UUID u, @IC@ armor) {
  if (tot == null) return 0;
  int[] c = note(u, armor);
  int ns = @PKG@.GearDefs.NS;
  int on = 0;
  for (int t = 0; t < TN.length; t++) {
    if (c[TSET[t]] < TN[t]) continue;
    int[] b = bonus(t);
    for (int k = 0; k < ns && k < tot.length && k < b.length; k++) tot[k] = @PKG@.GearStats.sat((long) tot[k] + (long) b[k]);
    on++;
  }
  return on;
}""")
M(gthm, r"""
public static float hp(java.util.UUID u, @IC@ armor) {
  int[] c = counts(u, armor);
  int ns = @PKG@.GearDefs.NS;
  float h = 0.0f;
  for (int t = 0; t < TN.length; t++) {
    if (c[TSET[t]] < TN[t]) continue;
    int[] b = bonus(t);
    if (b.length > ns && b[ns] > 0) h = h + (float) b[ns];
  }
  return h;
}""")
M(gthm, r"""
public static String activeText(java.util.UUID u, @IC@ armor) {
  int[] c = counts(u, armor);
  StringBuilder sb = new StringBuilder();
  for (int t = 0; t < TN.length; t++) {
    if (c[TSET[t]] < TN[t]) continue;
    if (sb.length() > 0) sb.append("; ");
    sb.append(SNAME[TSET[t]]).append(" ").append(TN[t]).append(" pieces: ").append(bonusText(t));
  }
  return sb.length() > 0 ? sb.toString() : "none";
}""")
M(gthm, r"""
public static void forget(java.util.UUID u) {
  if (u == null) return;
  String k0 = u.toString();
  java.util.Iterator it = new java.util.ArrayList(WORN.keySet()).iterator();
  while (it.hasNext()) {
    String k = (String) it.next();
    if (k.equals(k0) || k.startsWith(k0 + "-p")) WORN.remove(k);
  }
}""")
'''
